        // تبدیل می‌کند که دیگر قابل تفسیر نیست.
        $value = strtr($value, [
            "\u{200C}" => '', "\u{200F}" => '', "\u{00A0}" => '',
            '-' => '/', '.' => '/', '\\' => '/', ' ' => '/',
        ]);

        return trim(preg_replace('#/+#', '/', $value), '/');
    }
